/**
 * main.js — self-contained Three.js anatomical kidney scene.
 *
 * No backend. Assets consumed (all generated by tools/, all with provenance):
 *   assets/kidney.glb             anatomical surfaces + baked renal fields
 *   assets/kidney_vessels.json    four tubular systems (Murray radii)
 *   assets/kidney_flow.json       flow paths with real v = Q/A per sample
 *   assets/kidney_model.json      haemodynamics, respiration, cardiac coupling
 *   assets/kidney_molecular.json  measured single-cell transporter expression
 *   assets/flow_report.json       per-level velocity audit (also used in-scene)
 *
 * Four views:
 *   organ      both kidneys, capsule, great vessels, the vascular cascade
 *   section    the hemisected kidneys: cortex, medullary pyramids, columns of
 *              Bertin, papillae, and the collecting system
 *   nephron    cortical and juxtamedullary nephrons at real proportions
 *   molecular  the metformin route across a polarised proximal tubule cell
 *
 * Public API (also used by the automated probe):
 *   const api = await createKidneyScene({ container, assetBase, view })
 *   api.setView(...), api.setPlaybackRate(x), api.setParticleDensity(f),
 *   api.setTreeVisible(name, on), api.setOverlay(which, on), api.dispose()
 *   window.__kidney3d  diagnostics for the headless benchmark
 */

import * as THREE from 'three';
import { GLTFLoader } from '../vendor/jsm/loaders/GLTFLoader.js';
import { OrbitControls } from '../vendor/jsm/controls/OrbitControls.js';
import { RoomEnvironment } from '../vendor/jsm/environments/RoomEnvironment.js';

import { RespirationField } from './motion.js';
import { makeParenchymaMaterial, makeVesselMaterial, makeGreatVesselMaterial }
  from './materials.js';
import { buildVesselMesh, TREE_COLOR } from './vessels.js';
import { FlowSystem } from './flow.js';
import { buildNephrons, MAGNIFICATION } from './nephron.js';
import { buildMolecular } from './molecular.js';
import { HUD, NARROW_PX } from './hud.js';

const NEPHRON_OFFSET = new THREE.Vector3(0, -1400, 0);
const MOLECULAR_OFFSET = new THREE.Vector3(0, -2600, 0);
// The post-glomerular network is 10-20 µm across inside a 120 mm organ. It is
// drawn at a DECLARED calibre magnification so the two-beds-in-series
// arrangement is visible at organ scale; positions and lengths stay true.
const GLOM_RADIUS_SCALE = 9.0;

export async function createKidneyScene (opts = {}) {
  const container = opts.container || document.body;
  const base = opts.assetBase || './assets/';
  const stage = (s) => { window.__kidney3dStage = s; };

  stage('renderer:begin');
  const renderer = new THREE.WebGLRenderer({
    antialias: true, powerPreference: 'high-performance', alpha: false
  });
  const narrow0 = container.clientWidth < NARROW_PX;
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, narrow0 ? 1.75 : 2));
  renderer.setSize(container.clientWidth, container.clientHeight);
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.05;
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  container.appendChild(renderer.domElement);
  stage('renderer:ok');

  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x070a10);
  const pmrem = new THREE.PMREMGenerator(renderer);
  scene.environment = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;
  scene.environmentIntensity = 0.6;
  stage('pmrem:ok');

  const camera = new THREE.PerspectiveCamera(
    40, container.clientWidth / container.clientHeight, 1, 20000);
  const controls = new OrbitControls(camera, renderer.domElement);
  controls.enableDamping = true;
  controls.dampingFactor = 0.07;
  controls.minDistance = 10;
  controls.maxDistance = 4000;

  const key = new THREE.DirectionalLight(0xfff1e8, 2.2); key.position.set(1, 1.0, 0.9);
  const fill = new THREE.DirectionalLight(0x9fc4ff, 0.65); fill.position.set(-1.1, 0.25, -0.5);
  const rim = new THREE.DirectionalLight(0xffcfc0, 1.0); rim.position.set(-0.3, -0.8, -1.0);
  scene.add(key, fill, rim, new THREE.AmbientLight(0x30405a, 0.7));

  // ------------------------------------------------------------------ assets
  stage('fetch:begin');
  const [vessels, flowSpec, model, molecular, flowRep, vesselRep, geoRep] =
    await Promise.all([
      fetch(base + 'kidney_vessels.json').then(r => r.json()),
      fetch(base + 'kidney_flow.json').then(r => r.json()),
      fetch(base + 'kidney_model.json').then(r => r.json()),
      fetch(base + 'kidney_molecular.json').then(r => r.json()),
      fetch(base + 'flow_report.json').then(r => r.json()),
      fetch(base + 'vessel_report.json').then(r => r.json()),
      fetch(base + 'geometry_report.json').then(r => r.json())
    ]);
  stage('fetch:ok');

  const gltf = await new GLTFLoader().loadAsync(base + 'kidney.glb');
  stage('glb:ok');

  // ------------------------------------------------------------ organ group
  const organ = new THREE.Group();
  scene.add(organ);
  const body = new THREE.Group();          // everything that breathes
  organ.add(body);

  const parenMat = makeParenchymaMaterial();
  const aortaMat = makeGreatVesselMaterial(0xa33c32);
  const ivcMat = makeGreatVesselMaterial(0x3f5f94);
  const vesselMats = {
    renal_artery: makeVesselMaterial(TREE_COLOR.renal_artery),
    renal_vein: makeVesselMaterial(TREE_COLOR.renal_vein),
    glomerular: makeVesselMaterial(TREE_COLOR.glomerular),
    collecting_system: makeVesselMaterial(TREE_COLOR.collecting_system,
                                          { opacity: 0.93 })
  };
  const allMats = [parenMat, aortaMat, ivcMat, ...Object.values(vesselMats)];

  let triOrgan = 0; let triSection = 0;
  const parts = {};
  gltf.scene.traverse((o) => {
    if (!o.isMesh) return;
    const g = o.geometry;
    if (!g.getAttribute('_field0')) {
      console.warn(`[kidney3d] mesh "${o.name}" lacks _field0; skipped`);
      return;
    }
    const mat = o.name === 'aorta' ? aortaMat : (o.name === 'ivc' ? ivcMat : parenMat);
    const mesh = new THREE.Mesh(g, mat);
    mesh.name = o.name;
    mesh.frustumCulled = false;
    body.add(mesh);
    parts[o.name] = mesh;
    const t = (g.index ? g.index.count : g.getAttribute('position').count) / 3;
    if (o.name.startsWith('cut_')) triSection += t; else triOrgan += t;
  });
  stage('surfaces:ok');

  // ------------------------------------------------------------ vessel trees
  const treeMeshes = {};
  const treeStats = {};
  for (const tree of vessels.trees) {
    const rScale = tree.name === 'glomerular' ? GLOM_RADIUS_SCALE : 1.0;
    const built = buildVesselMesh(tree, { rScale });
    const mesh = new THREE.Mesh(built.geometry, vesselMats[tree.name]);
    mesh.name = 'tree_' + tree.name;
    mesh.frustumCulled = false;
    body.add(mesh);
    treeMeshes[tree.name] = mesh;
    treeStats[tree.name] = built.stats;
    triOrgan += built.stats.triangles;
  }
  stage('vessels:ok');

  // ------------------------------------------------------------------- flow
  const narrowNow = () => container.clientWidth < NARROW_PX;
  const basePPP = opts.particlesPerPath || (narrowNow() ? 70 : 150);
  const flow = new FlowSystem(flowSpec, basePPP);
  flow.setPixelRatio(renderer.getPixelRatio());
  body.add(flow.points);
  stage('flow:ok');

  // ------------------------------------------------------------- respiration
  const cranial = new THREE.Vector3(0, 1, 0);
  const bb = new THREE.Box3();
  for (const n of ['capsule_left', 'capsule_right']) {
    if (parts[n]) bb.expandByObject(parts[n]);
  }
  const organCentre = bb.getCenter(new THREE.Vector3());
  const resp = new RespirationField(model.respiration, cranial, organCentre,
                                    { excursionCm: opts.excursionCm });
  stage('respiration:ok');

  // --------------------------------------------------------------- nephron
  const neph = buildNephrons(model, flowRep);
  neph.group.position.copy(NEPHRON_OFFSET);
  scene.add(neph.group);
  const nephFlow = new FlowSystem(neph.flowSpec, narrowNow() ? 40 : 80);
  nephFlow.setPixelRatio(renderer.getPixelRatio());
  nephFlow.setParticleScale(1.6);
  neph.group.add(nephFlow.points);
  stage('nephron:ok');

  // -------------------------------------------------------------- molecular
  const mol = buildMolecular(molecular);
  mol.group.position.copy(MOLECULAR_OFFSET);
  scene.add(mol.group);
  const molFlow = new FlowSystem(mol.flowSpec, narrowNow() ? 70 : 140);
  molFlow.setPixelRatio(renderer.getPixelRatio());
  molFlow.setParticleScale(2.2);
  mol.group.add(molFlow.points);
  stage('molecular:ok');

  // The collecting system and the glomerular network start hidden in the organ
  // view: showing all four systems at once is an unreadable thicket. The page
  // exposes the toggles and the section view turns the collecting system on.
  treeMeshes.collecting_system.visible = false;
  flow.setTreeEnabled('collecting_system', false);

  // ------------------------------------------------------------- anatomy labels
  // Anchored on real geometry from the landmark/vessel data, not placed by eye.
  const organLabels = [];
  const vtree = Object.fromEntries(vessels.trees.map(t => [t.name, t]));
  function anchorOf (treeName, levelPrefix, nth = 0) {
    const t = vtree[treeName];
    if (!t) return null;
    let seen = 0;
    for (let i = 0; i < t.label.length; i++) {
      if (String(t.label[i]).startsWith(levelPrefix)) {
        if (seen++ === nth) return new THREE.Vector3().fromArray(t.nodes[i]);
      }
    }
    return null;
  }
  const L = (treeName, prefix, text, color, pri, nth) => {
    const p = anchorOf(treeName, prefix, nth || 0);
    if (p) organLabels.push({ pos: p, text, color, pri });
  };
  L('renal_artery', 'renal_artery_left', 'renal artery (ostium on the real aorta)',
    '#ff7a68', 10, 0);
  L('renal_vein', 'renal_vein_left', 'renal vein (ostium on the real cava)',
    '#7aa6e8', 10, 0);
  L('renal_artery', 'segmental_apical_left', 'segmental artery (5 per kidney)',
    '#ff9070', 8);
  L('renal_artery', 'interlobar_left', 'interlobar artery — runs in a column of Bertin',
    '#ff9f72', 9, 6);
  L('renal_artery', 'arcuate_left', 'ARCUATE artery — arcs along the corticomedullary junction',
    '#ffab74', 11, 10);
  L('renal_artery', 'cortical_radiate_left', 'cortical radiate (interlobular) artery',
    '#ffbe92', 7, 40);
  L('glomerular', 'glomerulus_left', 'glomerulus — 1st capillary bed', '#ffcc55', 12, 12);
  L('glomerular', 'efferent_left', 'EFFERENT arteriole — between the two beds',
    '#ff9b5c', 12, 4);
  L('glomerular', 'peritubular_left', 'peritubular capillaries — 2nd bed (cortex)',
    '#ffc28a', 11, 30);
  L('glomerular', 'vasa_recta_descending_left', 'VASA RECTA — 2nd bed (medulla)',
    '#ff9a5c', 12, 6);
  L('renal_artery', 'cortical_radiate_right', 'cortex', '#e0b0a0', 4, 120);
  const sectionLabels = [];
  const SL = (treeName, prefix, text, color, pri, nth) => {
    const p = anchorOf(treeName, prefix, nth || 0);
    if (p) sectionLabels.push({ pos: p, text, color, pri });
  };
  SL('collecting_system', 'minor_calyx_left', 'minor calyx (cups a papilla)',
     '#e8e8a8', 10, 2);
  SL('collecting_system', 'major_calyx_middle_left', 'major calyx', '#e8e8a8', 10);
  SL('collecting_system', 'ureter_left', 'renal pelvis -> ureter', '#e8e8a8', 11, 8);
  SL('renal_artery', 'arcuate_left', 'corticomedullary junction', '#ffab74', 9, 4);
  SL('renal_artery', 'interlobar_left', 'column of Bertin', '#f0d0a0', 9, 2);

  // ------------------------------------------------------------------- view
  let view = opts.view || 'organ';
  scene.updateMatrixWorld(true);
  function boxOf (objs) {
    const b = new THREE.Box3();
    for (const o of objs) if (o) b.expandByObject(o);
    return b;
  }
  const organBox = boxOf(['capsule_left', 'capsule_right', 'aorta', 'ivc']
    .map(n => parts[n]));
  const sectionBox = boxOf(['cut_left', 'cut_right'].map(n => parts[n]));
  const nephBox = new THREE.Box3();
  neph.group.traverse(o => { if (o.isMesh) nephBox.expandByObject(o); });
  const molBox = new THREE.Box3();
  mol.group.traverse(o => { if (o.isMesh) molBox.expandByObject(o); });
  const FRAMES = {
    organ: { box: organBox, margin: 0.92 },
    section: { box: sectionBox, margin: 0.95 },
    nephron: { box: nephBox, margin: 1.12 },
    molecular: { box: molBox, margin: 1.05 }
  };

  function frameView (v) {
    const f = FRAMES[v] || FRAMES.organ;
    const centre = f.box.getCenter(new THREE.Vector3());
    const radius = Math.max(f.box.getSize(new THREE.Vector3()).length() * 0.5, 1);
    const fov = THREE.MathUtils.degToRad(camera.fov);
    const aspect = Math.max(camera.aspect, 0.35);
    const dist = radius / Math.sin(Math.min(fov / 2,
      Math.atan(Math.tan(fov / 2) * aspect)));
    controls.target.copy(centre);
    const dir = v === 'molecular' ? new THREE.Vector3(0.35, 0.55, 1.0)
      : new THREE.Vector3(0.55, 0.28, 1.0);
    camera.position.copy(centre).add(dir.normalize().multiplyScalar(dist * f.margin));
    camera.near = Math.max(radius * 0.004, 0.05);
    camera.far = radius * 80;
    camera.updateProjectionMatrix();
    controls.update();
  }

  const LIGHT_BASE = { key: 2.2, fill: 0.65, rim: 1.0, env: 0.6, exposure: 1.05 };
  function setView (v) {
    view = v;
    organ.visible = (v === 'organ' || v === 'section');
    neph.group.visible = (v === 'nephron');
    mol.group.visible = (v === 'molecular');
    const sect = (v === 'section');
    for (const n of ['capsule_left', 'capsule_right', 'aorta', 'ivc']) {
      if (parts[n]) parts[n].visible = !sect;
    }
    for (const n of ['medulla_left', 'medulla_right']) {
      if (parts[n]) parts[n].visible = !sect && showMedulla;
    }
    for (const n of ['cut_left', 'cut_right', 'cut_medulla_left', 'cut_medulla_right']) {
      if (parts[n]) parts[n].visible = sect;
    }
    if (sect) {
      treeMeshes.collecting_system.visible = true;
      flow.setTreeEnabled('collecting_system', true);
    }
    const dim = (v === 'nephron' || v === 'molecular') ? 0.55 : 1.0;
    key.intensity = LIGHT_BASE.key * dim;
    fill.intensity = LIGHT_BASE.fill * (v === 'molecular' ? 1.3 : dim);
    rim.intensity = LIGHT_BASE.rim * dim;
    scene.environmentIntensity = LIGHT_BASE.env * (dim < 1 ? 0.75 : 1.0);
    renderer.toneMappingExposure = LIGHT_BASE.exposure;
    frameView(v);
  }

  // --------------------------------------------------------------------- HUD
  const hudCanvas = document.createElement('canvas');
  hudCanvas.style.cssText = 'position:absolute;inset:0;pointer-events:none;z-index:5';
  container.appendChild(hudCanvas);
  const hud = new HUD(hudCanvas);
  let showLabels = true;
  let showMedulla = true;

  let densityUser = 1.0;
  function applyDensity () {
    const narrow = narrowNow();
    const f = densityUser * (narrow ? 0.45 : 1.0);
    flow.setDensity(f); nephFlow.setDensity(f); molFlow.setDensity(f);
    flow.setParticleScale(narrow ? 0.85 : 1.0);
    nephFlow.setParticleScale(narrow ? 1.25 : 1.6);
    molFlow.setParticleScale(narrow ? 1.7 : 2.2);
  }

  function resize () {
    const w = container.clientWidth; const h = container.clientHeight;
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, w < NARROW_PX ? 1.75 : 2));
    renderer.setSize(w, h, false);
    camera.aspect = w / h;
    camera.updateProjectionMatrix();
    // the HUD is text on a 2-D canvas; it gains nothing from a 2x buffer
    hud.resize(w, h, Math.min(renderer.getPixelRatio(), 1.5));
    flow.setPixelRatio(renderer.getPixelRatio());
    nephFlow.setPixelRatio(renderer.getPixelRatio());
    molFlow.setPixelRatio(renderer.getPixelRatio());
    applyDensity();
    frameView(view);
  }
  window.addEventListener('resize', resize);
  resize();
  setView(view);
  applyDensity();

  // ------------------------------------------------------------------- clock
  let simMs = 0;
  let playbackRate = 1.0;
  let running = true;
  let lastNow = performance.now();
  const frameTimes = [];
  let frameCount = 0;
  let hudAccum = 1e9;

  const hm = model.haemodynamics;
  const lv = flowRep.levels;
  const colOf = (hex) => '#' + hex.toString(16).padStart(6, '0');
  const _lw = new WeakMap();
  function worldLabels (labels, group) {
    group.updateMatrixWorld(true);
    let cache = _lw.get(labels);
    if (!cache) { cache = labels.map(L => ({ ...L, pos: L.pos.clone() })); _lw.set(labels, cache); }
    for (let i = 0; i < labels.length; i++) {
      cache[i].pos.copy(labels[i].pos).applyMatrix4(group.matrixWorld);
    }
    return cache;
  }
  const fmt = (k) => (lv[k] ? lv[k].time_averaged_velocity_cm_s.toFixed(1) + ' cm/s' : 'n/a');

  const diag = {
    triangles: triOrgan,
    sectionTriangles: triSection,
    nephronTriangles: neph.info.triangles,
    molecularTriangles: mol.info.triangles,
    particles: flow.nParticles,
    trees: treeStats,
    flow: flow.diagnostics(),
    nephron: neph.info,
    molecular: mol.info,
    respiration: resp.describe(),
    haemodynamics: {
      rbf_mL_min: hm.renal_blood_flow_mL_min,
      gfr_mL_min: hm.gfr_mL_min,
      rpf_mL_min: hm.renal_plasma_flow_mL_min,
      filtration_fraction: hm.filtration_fraction,
      map_mmHg: hm.mean_arterial_pressure_mmHg,
      glomerular_capillary_mmHg: hm.pressures.glomerular_capillary_mmHg,
      ordinary_capillary_mmHg: hm.pressures.ordinary_systemic_capillary_mmHg,
      net_filtration_pressure_mmHg: hm.pressures.net_filtration_pressure_mmHg
    },
    levels: lv,
    glomerularRadiusScale: GLOM_RADIUS_SCALE,
    geometry: geoRep.kidneys,
    vesselReport: {
      murray: Object.fromEntries(Object.entries(vesselRep.trees).map(
        ([k, v]) => [k, v.murray_max_relative_residual])),
      clearance: vesselRep.cross_tree_clearance.worst_min_surface_gap_mm
    },
    ready: false
  };

  function flowRows () {
    if (view === 'nephron') {
      const n = neph.info.nephrons;
      return [
        { name: 'proximal tubule', value: n.cortical.tubular_velocity_mm_s.proximal_tubule.toFixed(3) + ' mm/s', color: '#d79a63' },
        { name: 'loop of Henle', value: n.cortical.tubular_velocity_mm_s.loop_of_henle.toFixed(3) + ' mm/s', color: '#9fc6dd' },
        { name: 'collecting duct', value: n.cortical.tubular_velocity_mm_s.collecting_duct.toFixed(3) + ' mm/s', color: '#e4e4a0' },
        { name: 'speed gain', value: neph.info.tubular_display_gain + 'x', color: '#9fb4cf' },
        { name: 'calibre gain', value: neph.info.tubule_calibre_gain + 'x (length true)', color: '#9fb4cf' }
      ];
    }
    if (view === 'molecular') {
      const r = molecular.metformin.route.filter(x => x.measured);
      return r.map(x => ({
        name: `${x.protein} ${x.membrane.slice(0, 7)}`,
        value: x.measured.mean_expr_log1p_cp10k.toFixed(3) + ' · '
               + x.measured.pct_expressing.toFixed(0) + '%',
        color: x.membrane === 'apical' ? '#f5b85a' : '#6fb6ec'
      })).concat([{ name: 'no flux calibration', value: 'qualitative only',
                    color: '#c0a0a0' }]);
    }
    return [
      { name: 'renal artery', value: fmt('renal_artery'), color: colOf(TREE_COLOR.renal_artery) },
      { name: 'arcuate artery', value: fmt('arcuate'), color: '#f07045' },
      { name: 'cortical radiate', value: fmt('cortical_radiate'), color: '#f78a5c' },
      { name: 'renal vein', value: fmt('renal_vein'), color: colOf(TREE_COLOR.renal_vein) },
      { name: 'afferent -> efferent', value: fmt('afferent') + ' -> ' + fmt('efferent'), color: '#ffc24d' },
      { name: 'urine (gain ' + flow.urineGain + 'x)', value: fmt('ureter'), color: colOf(TREE_COLOR.collecting_system) }
    ];
  }

  function frame (now) {
    if (!running) return;
    // requestAnimationFrame hands back the FRAME's start timestamp, which can
    // precede the performance.now() captured just before the loop started, so
    // the first delta can be negative. Clamp it: a negative dt ran the cardiac
    // phase backwards, JS's % preserved the sign, and pulse[-k] came back
    // undefined — which poisoned every particle phase with NaN and silently
    // froze the whole flow field.
    const wallDt = Math.max(0, Math.min(now - lastNow, 100));
    lastNow = now;
    frameTimes.push(wallDt);
    if (frameTimes.length > 900) frameTimes.shift();
    frameCount++;
    const dtSim = wallDt * playbackRate;
    simMs += dtSim;

    const m = resp.update(simMs);
    body.matrixAutoUpdate = false;
    body.matrix.copy(m);
    body.matrixWorldNeedsUpdate = true;

    if (view === 'nephron') nephFlow.update(dtSim, 1.0);
    else if (view === 'molecular') molFlow.update(dtSim, 1.0);
    else flow.update(dtSim, 1.0);

    controls.update();
    renderer.render(scene, camera);

    const act = view === 'nephron' ? nephFlow : (view === 'molecular' ? molFlow : flow);
    hud.tickFps(now);
    // The HUD is static between user actions, so repainting it at the render
    // rate is wasted canvas work; 10 Hz is indistinguishable and much cheaper.
    hudAccum += wallDt;
    if (hudAccum < 100) { requestAnimationFrame(frame); return; }
    hudAccum = 0;
    hud.draw({
      fps: hud.fps,
      triangles: view === 'nephron' ? neph.info.triangles
        : (view === 'molecular' ? mol.info.triangles
          : (view === 'section' ? triSection : triOrgan)),
      particlesDrawn: act.drawn || act.nParticles,
      view,
      magnification: view === 'nephron' ? MAGNIFICATION : null,
      heart: { bpm: hm.heart_rate_bpm, phase01: flow.cardiacPhase01,
               pulse: flow.pulseNow },
      respiration: { phase01: resp.phase01,
                     breaths_per_min: resp.breathsPerMin,
                     displacement_mm: resp.displacementMm },
      flowTitle: view === 'molecular' ? 'MEASURED EXPRESSION (CP10K log1p)'
        : (view === 'nephron' ? 'TUBULAR FLUID — v = Q/A' : 'BLOOD — v = Q/A'),
      flowRows: flowRows(),
      note: view === 'molecular'
        ? `${molecular.source.total_cells.toLocaleString()} cells · ${molecular.source.cell_types} cell types · no flux calibration`
        : 'TotalSegmentator v2 CC-BY-4.0 · s0236 · constructed cortex/medulla'
    });
    if (showLabels) {
      // Nephron and molecular labels are authored in their group's LOCAL frame,
      // and those groups sit at a large offset, so they have to be taken to
      // world space before projecting — otherwise every one of them lands
      // behind the camera and is culled, which is exactly what happened.
      let set;
      if (view === 'nephron') set = worldLabels(neph.labels, neph.group);
      else if (view === 'molecular') set = worldLabels(mol.labels, mol.group);
      else set = view === 'section' ? sectionLabels : organLabels;
      hud.drawLabels(set, camera, THREE);
    }
    requestAnimationFrame(frame);
  }
  stage('loop:start');
  requestAnimationFrame(frame);
  diag.ready = true;
  stage('ready');

  const api = {
    renderer, scene, camera, controls, hud, organ, body,
    nephron: neph.group, molecularGroup: mol.group,
    flow, nephFlow, molFlow, resp, parts, treeMeshes, diag, model, vessels,
    molecular, flowReport: flowRep,
    get simMs () { return simMs; },
    get view () { return view; },
    setView,
    views: ['organ', 'section', 'nephron', 'molecular'],
    setPlaybackRate (x) { playbackRate = x; },
    setParticleDensity (f) { densityUser = f; applyDensity(); },
    setLabelsVisible (on) { showLabels = !!on; },
    setTreeVisible (name, on) {
      if (treeMeshes[name]) treeMeshes[name].visible = on;
      flow.setTreeEnabled(name, on);
    },
    setPartVisible (name, on) { if (parts[name]) parts[name].visible = on; },
    setOverlay (which, on) {
      const v = on ? 1.0 : 0.0;
      for (const m of allMats) {
        const u = m.userData.uniforms;
        if (!u) continue;
        if (which === 'pyramids') u.uPyramidTint.value = v;
        if (which === 'columns') u.uColumns.value = on ? 1.0 : 0.0;
        if (which === 'zone') u.uZone.value = v;
        if (which === 'cortexMedulla') u.uCortexMedulla.value = on ? 1.0 : 0.0;
      }
      if (which === 'medulla') {
        showMedulla = on;
        for (const n of ['medulla_left', 'medulla_right']) {
          if (parts[n]) parts[n].visible = on && view === 'organ';
        }
      }
    },
    frameStats () {
      const a = frameTimes.slice().sort((x, y) => x - y);
      const mean = a.reduce((s, v) => s + v, 0) / Math.max(a.length, 1);
      return {
        frames: frameCount, meanFrameMs: mean,
        medianFrameMs: a.length ? a[Math.floor(a.length / 2)] : NaN,
        p95FrameMs: a.length ? a[Math.floor(a.length * 0.95)] : NaN,
        fpsMean: 1000 / mean,
        fpsMedian: a.length ? 1000 / a[Math.floor(a.length / 2)] : NaN
      };
    },
    resetFrameStats () { frameTimes.length = 0; frameCount = 0; },
    /**
     * Cost of one render, measured WITHOUT requestAnimationFrame.
     * Headless Chromium drives rAF from its compositor at a fixed cadence, so
     * a frame-rate read from rAF measures that cadence, not the scene. This
     * renders n times back to back and waits for the GPU, which is the real
     * per-frame cost; fps = 1000 / msPerFrame.
     */
    renderCost (n = 60) {
      const gl = renderer.getContext();
      renderer.render(scene, camera);
      gl.finish();
      const t0 = performance.now();
      for (let i = 0; i < n; i++) renderer.render(scene, camera);
      gl.finish();
      const ms = (performance.now() - t0) / n;
      return { frames: n, msPerFrame: ms, fps: 1000 / ms };
    },
    hudOverflow () { return hud.overflow(); },
    dispose () {
      running = false;
      window.removeEventListener('resize', resize);
      renderer.dispose();
    }
  };

  window.__kidney3d = api;
  return api;
}
